"""Complete 24 original resuscitation and post-arrest questions."""
from create_critical_resuscitation import rows,q,BL,AL,PO,ER,ref
from qbank_authoring import finalize

q('According to AHA 2025 adult post-arrest guidance, once reliable oxygen measurements are available after ROSC, which SpO2 target range is reasonable?', '90–98%',[
 ('Keep FiO2 at 1.0 indefinitely regardless of PaO2','Avoidable hyperoxemia is not the target once reliable measurement is available.'),('75–85%','This permits clinically important hypoxemia.'),('100% as an obligatory minimum','This is impossible as a minimum and encourages excessive oxygen delivery.')],
 'Titrate after the initial emergency oxygen phase','**Avoid both hypoxemia and unnecessary hyperoxemia after ROSC.**',['The question uses the explicitly named AHA range.','Other guidance may specify a narrower operational target.'],'**Use reliable saturation and arterial gas information.**',['Poor perfusion and measurement error can mislead pulse oximetry.','Reassess when ventilation or hemodynamics change.'],[['AHA SpO2','90–98%'],['Initial uncertainty','Provide sufficient oxygen'],['Later','Titrate with reliable measurements']],[PO])

q('An intubated adult after ROSC has no major acid-base indication for an alternative target. Which PaCO2 strategy is appropriate?', 'Target normocapnia, generally 35–45 mmHg, while assessing the individual context',[
 ('Routine marked hypocapnia below 25 mmHg','Cerebral vasoconstriction can compromise perfusion.'),('Routine severe hypercapnia above 80 mmHg','This is not the standard universal post-arrest target.'),('Use respiratory rate alone without blood gases','The same rate can produce very different CO2 levels.')],
 'Brain perfusion is sensitive to CO2','**Avoid unplanned hypo- or hyperventilation.**',['Dead space and metabolic CO2 production may change after arrest.','Severe metabolic acidemia and chronic respiratory disease may require individualized decisions.'],'**Use arterial gases to verify the ventilation effect.**',['ETCO2 can differ substantially from PaCO2 during low perfusion.','Continue lung-protective ventilation as appropriate.'],[['Usual target','PaCO2 35–45'],['Hypocapnia','Cerebral vasoconstriction'],['Monitoring','Blood gas plus clinical context']],[PO])

q('After ROSC, a patient has MAP 52 mmHg and poor peripheral perfusion. What is the appropriate principle?', 'Treat hypotension and identify myocardial dysfunction, vasoplegia, volume issues or ongoing obstruction',[
 ('Accept this pressure because a pulse has returned','ROSC does not guarantee adequate organ perfusion.'),('Give the same fixed fluid volume to every patient','The cause and fluid tolerance vary.'),('Use a single vasopressor choice as proven best for all postarrest patients','Agent selection depends on physiology and evidence limitations.')],
 'Circulation needs active support after the arrest ends','**Post-arrest shock can involve several mechanisms.**',['AHA guidance supports avoiding hypotension, with MAP at least sixty-five as a practical minimum.','Higher individual targets may be appropriate but are not universally beneficial.'],'**Use echo, examination and response to guide support.**',['Track lactate trends and organ perfusion without treating one marker in isolation.','Investigate the arrest cause and recurrent ischemia.'],[['Problem','Post-arrest hypotension'],['Assessment','Pump/vascular/volume/obstructive causes'],['Treatment','Physiology-guided support']],[PO],style='clinical_scenario')

q('A comatose patient after ROSC has persistent ST elevation consistent with acute coronary occlusion. Which approach is appropriate?', 'Emergency coronary angiography with reperfusion when indicated',[
 ('Wait for neurological awakening before coronary evaluation','Coma alone does not justify delaying reperfusion for a clear occlusion pattern.'),('Treat every postarrest troponin elevation identically without considering ECG or context','Troponin can rise after arrest for several reasons.'),('Exclude acute coronary occlusion because CPR itself can cause ECG changes','Alternative explanations require assessment but do not negate a convincing persistent STEMI pattern.')],
 'Treat a reversible arrest cause promptly','**Persistent ST elevation after ROSC can indicate an acutely occluded coronary artery.**',['Evaluate the full ECG and clinical context.','Hemodynamic or electrical instability can add urgency.'],'**Coordinate post-arrest organ support with coronary intervention.**',['Avoid premature pessimistic neurological decisions.','Address shock and recurrent dysrhythmias concurrently.'],[['Persistent STEMI','Emergency coronary pathway'],['Coma','Not an automatic reason to defer'],['Support','Concurrent ICU care']],[PO],style='clinical_scenario')

q('A comatose survivor of out-of-hospital arrest has no ST elevation, no shock, no recurrent ventricular arrhythmia and no ongoing ischemia. What is the evidence-based coronary strategy?', 'Routine immediate angiography has not shown benefit over a delayed/selective approach in this stable group',[
 ('Every comatose survivor requires immediate catheterization regardless of findings','Trials do not support this universal strategy in the defined stable population.'),('Coronary disease is excluded and should never be investigated','A selective or later assessment can still be indicated.'),('The stable-population evidence prohibits emergency angiography if shock develops','New instability changes the decision.')],
 'Do not apply the stable no-STEMI trials to unstable patients','**Absence of a routine immediate benefit is population-specific.**',['Ongoing ischemia, shock and recurrent malignant arrhythmias are important exceptions.','Assess noncoronary causes and the overall clinical trajectory.'],'**Use a selective plan rather than a blanket rule.**',['Continue ECG and hemodynamic surveillance.','Reassess promptly if new evidence of coronary instability appears.'],[['Stable/no STEMI','Delayed/selective strategy'],['Persistent STEMI','Emergency pathway'],['New shock/arrhythmia','Reconsider urgent intervention']],[PO,ref('COACT randomized coronary angiography trial','https://doi.org/10.1056/NEJMoa1816897'),ref('TOMAHAWK randomized trial','https://doi.org/10.1056/NEJMoa2101909')],style='clinical_scenario')

q('An adult remains unable to follow commands after ROSC off confounding sedation. Which temperature principle is appropriate?', 'Use deliberate protocolized temperature control and active fever prevention rather than leaving temperature unmanaged',[
 ('Every patient must receive 33°C because it is proven superior in all subgroups','No single low target has universal demonstrated superiority.'),('Fever is beneficial and should be deliberately induced','Fever is not a recommended recovery strategy.'),('Temperature management is needed only after VF and never after nonshockable arrest','The approach is not restricted to one initial rhythm.')],
 'Temperature care includes preventing fever','**AHA guidance allows a controlled target within thirty-two to thirty-seven-point-five degrees.**',['Target choice considers patient and system factors.','A controlled normothermic strategy still requires active monitoring and intervention.'],'**Follow a complete temperature protocol including rewarming and ongoing fever prevention.**',['Avoid rapid uncontrolled changes.','Account for sedation and shivering when examining neurological function.'],[['Target','Selected controlled range'],['Fever','Actively prevent'],['Examination','Interpret temperature/sedation effects']],[PO])

q('A patient has early generalized myoclonus after cardiac arrest. Which statement is correct?', 'Myoclonus requires EEG and clinical characterization and should not alone determine a hopeless prognosis',[
 ('Any early myoclonus proves irreversible poor outcome with certainty','The phenotype, EEG background and other evidence matter.'),('All myoclonus is necessarily an electrographic seizure','Movement and ictal EEG activity are not identical.'),('Neuromuscular paralysis alone treats cortical seizure activity','It can hide movement without treating the electrical process.')],
 'Separate movement, seizures and prognosis','**Post-arrest myoclonus has heterogeneous mechanisms and outcomes.**',['Use EEG to assess electrographic seizures and the background.','Sedation and metabolic factors can complicate interpretation.'],'**Treat indicated seizures and use delayed multimodal prognostication.**',['Do not suppress movement solely to create a misleadingly normal examination.','Communicate uncertainty accurately to the family.'],[['Movement','Characterize clinically'],['EEG','Seizure/background assessment'],['Prognosis','Not one sign alone']],[PO,ER],style='clinical_scenario')

q('A comatose post-arrest patient has recurrent electrographic seizures. What is appropriate?', 'Treat identified seizures and use EEG to monitor response',[
 ('Ignore seizures unless there are visible convulsions','Sedation or paralysis can conceal clinical movements.'),('Give routine antiseizure prophylaxis to every patient as a proven outcome-improving strategy','Universal prophylaxis is not the same as treatment of documented seizures.'),('Use paralysis alone as definitive antiseizure treatment','Neuromuscular blockade does not stop cortical seizure activity.')],
 'Electrical seizures can persist without obvious movement','**EEG guides detection and treatment monitoring.**',['Treatment choice accounts for hemodynamics and drug interactions.','The broader injury pattern and EEG background remain relevant.'],'**Correct metabolic contributors and continue structured neurological care.**',['Avoid interpreting treated/sedated examinations without confounder review.','Use multiple domains for prognosis.'],[['Detection','EEG'],['Documented seizures','Treat'],['Prophylaxis','No universal demonstrated benefit']],[PO,ER],style='clinical_scenario')

q('Which approach is appropriate for neurological prognostication in a persistently comatose cardiac-arrest survivor?', 'Delayed multimodal assessment after adequate time and clearance of major confounders',[
 ('Use the first-hour motor score as a definitive standalone prediction','Early findings are heavily confounded and can evolve.'),('Use one biomarker value regardless of assay, timing or hemolysis','Biomarkers require context and corroboration.'),('Assume a fixed clock time overrides residual sedation, hypothermia and metabolic abnormalities','Confounders can delay a reliable assessment.')],
 'Avoid a self-fulfilling premature prediction','**Examination, EEG, evoked potentials, imaging and selected biomarkers provide complementary evidence.**',['Conclusions are generally deferred to at least seventy-two hours in the appropriate post-ROSC/rewarming framework.','Sedative clearance can be prolonged by organ dysfunction.'],'**Resolve discordant findings and communicate uncertainty.**',['Separate prognosis from the patient’s values and broader treatment goals.','Repeat assessment when the evidence is not concordant.'],[['Timing','Delayed and confounder-aware'],['Evidence','Multiple independent domains'],['Discordance','Reassess rather than force certainty']],[PO,ER])

q('Why can sedative clearance after cardiac arrest take longer than expected from a usual drug half-life?', 'Hypothermia, organ dysfunction, prolonged infusion and active metabolites can delay drug effects',[
 ('A single standard half-life guarantees a normal examination in every ICU patient','Clearance and pharmacodynamics vary substantially.'),('Neuromuscular blockers restore consciousness while hiding weakness','They do not restore consciousness and can mask motor responses.'),('A normal serum creatinine excludes every pharmacological confounder','Hepatic clearance, metabolites and other factors also matter.')],
 'The neurological examination is also a pharmacological examination','**Drug exposure can obscure consciousness, movement and reflex assessment.**',['Consider dose history, infusion duration and temperature.','Review organ function and interacting agents.'],'**Allow adequate clearance and use supporting tests appropriately.**',['Do not confuse an absent response during paralysis with irreversible injury.','Document confounders explicitly before prognostic decisions.'],[['Drug history','Dose and duration'],['Physiology','Temperature and organ function'],['Interpretation','Confounder-aware']],[PO,ER])

q('A cardiac-arrest survivor is awake but has memory difficulty, fatigue and anxiety before discharge. Which plan is appropriate?', 'Assess cognitive, physical and psychological recovery needs and arrange rehabilitation and follow-up',[
 ('Discharge without assessment because command following proves full recovery','Subtle disability can persist despite apparent neurological recovery.'),('Restrict follow-up to the ejection fraction alone','Cardiac, cognitive and psychological domains all matter.'),('Assume all symptoms will resolve without support','Recovery varies and treatable needs should be identified.')],
 'Outcome extends beyond survival and a bedside command','**Post-arrest impairment can affect independence, work and family life.**',['Evaluate the cause of arrest and secondary prevention.','Screen for emotional distress and caregiver burden.'],'**Provide a coordinated recovery and prevention plan.**',['Include medication review, rehabilitation and appropriate cardiac protection.','Communicate warning symptoms and follow-up arrangements clearly.'],[['Physical','Strength and endurance'],['Cognitive','Memory/attention'],['Psychological','Anxiety and trauma symptoms']],[PO,ER],style='clinical_scenario')

q('After ROSC, why should the team continue searching for the arrest cause even when circulation stabilizes?', 'A persistent reversible cause can trigger rearrest or remain untreated despite temporary physiological recovery',[
 ('ROSC proves that the cause has been permanently removed','Resuscitation can restore circulation without correcting coronary, pulmonary, metabolic or toxicological disease.'),('Cause evaluation is useful only for VF and never for PEA','All rhythm categories can have treatable underlying causes.'),('A single normal laboratory panel excludes all important causes','Imaging, history, ECG and serial examination may still be essential.')],
 'Resuscitation success creates time for definitive treatment','**Post-arrest stabilization and cause identification are parallel tasks.**',['Use the circumstances, ECG, echo and targeted imaging/laboratory assessment.','Consider noncardiac causes when the history or examination suggests them.'],'**Treat the cause and plan recurrence prevention.**',['Monitor continuously for recurrent instability.','Use a structured team handoff so no causal clue is lost.'],[['ROSC','Restored circulation'],['Definitive care','Treat the cause'],['Prevention','Reduce recurrence risk']],[PO],style='clinical_scenario')

if __name__=='__main__':finalize('Critical Care and Toxicology',8,'Resuscitation and Post-arrest Care','critical-resuscitation',rows,24)
